<script setup>
import{computed,onMounted,ref}from'vue';import{apiErrorMessage,showToast}from'./uiFeedback';
const apiBase=import.meta.env.VITE_API_BASE||'/api',token=localStorage.getItem('support_token')||'';const agents=ref([]),audit=ref([]),loading=ref(false),fileOpen=ref(false),fileAgent=ref(null),filePath=ref('/'),fileItems=ref([]),fileLoading=ref(false),uploadInput=ref(null);
const onlineCount=computed(()=>agents.value.filter(a=>Number(a.online)===1).length);function headers(e={}){return{...e,Authorization:`Bearer ${token}`}}async function request(u,o={}){o.headers=headers(o.headers||{});let r=await fetch(u,o);if(!r.ok)throw new Error(await apiErrorMessage(r));return r.json()}function time(v){return v?String(v).replace('T',' ').slice(0,19):'-'}
async function load(){loading.value=true;try{[agents.value,audit.value]=await Promise.all([request(`${apiBase}/admin/remote/agents`),request(`${apiBase}/admin/remote/audit?limit=50`)])}catch(e){showToast(e.message)}finally{loading.value=false}}
async function openFiles(a){fileAgent.value=a;fileOpen.value=true;filePath.value='/';await listFiles('/')}async function listFiles(p){fileLoading.value=true;try{let r=await request(`${apiBase}/admin/remote/agents/${fileAgent.value.id}/files?path=${encodeURIComponent(p)}`);filePath.value=r.path;fileItems.value=r.items||[]}catch(e){showToast(e.message)}finally{fileLoading.value=false}}function join(n){return(filePath.value==='/'?'':filePath.value)+'/'+n}function up(){if(filePath.value==='/')return;let p=filePath.value.replace(/\/+$/,'').replace(/\/[^/]+$/,'')||'/';listFiles(p)}function size(n){if(!n)return'0 B';for(let u of['B','KB','MB','GB','TB']){if(n<1024)return`${n.toFixed?n.toFixed(n<10&&u!=='B'?1:0):n} ${u}`;n/=1024}}
async function downloadFile(x){try{let r=await request(`${apiBase}/admin/remote/agents/${fileAgent.value.id}/files/download?path=${encodeURIComponent(join(x.name))}`);let raw=atob(r.data),b=new Uint8Array(raw.length);for(let i=0;i<raw.length;i++)b[i]=raw.charCodeAt(i);let url=URL.createObjectURL(new Blob([b])),a=document.createElement('a');a.href=url;a.download=r.name;a.click();URL.revokeObjectURL(url)}catch(e){showToast(e.message)}}
async function uploadFiles(ev){for(let f of ev.target.files||[]){if(f.size>50*1024*1024){showToast(`${f.name} 超过 50MB`);continue}let data=await new Promise((ok,no)=>{let r=new FileReader;r.onload=()=>ok(String(r.result).split(',')[1]);r.onerror=no;r.readAsDataURL(f)});let path=join(f.name);try{await request(`${apiBase}/admin/remote/agents/${fileAgent.value.id}/files/upload`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({path,data,overwrite:false})});showToast(`${f.name} 上传成功`,'success')}catch(e){if(confirm(`${f.name}: ${e.message}\n是否覆盖？`))await request(`${apiBase}/admin/remote/agents/${fileAgent.value.id}/files/upload`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({path,data,overwrite:true})})}}ev.target.value='';await listFiles(filePath.value)}async function mkdir(){let n=prompt('新文件夹名称');if(!n||n.includes('/'))return;try{await request(`${apiBase}/admin/remote/agents/${fileAgent.value.id}/files/mkdir`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({path:join(n)})});await listFiles(filePath.value)}catch(e){showToast(e.message)}}
onMounted(load)
</script>
<template><main class="page remote-page"><section class="admin-header"><div><span class="badge">MYROBOOT REMOTE</span><h1>远程运维中心</h1><p>Agent 0.3.0 增加远程文件管理。</p></div><div class="header-actions"><a class="back-link" href="/admin">返回管理后台</a><button class="secondary" @click="load">{{loading?'刷新中…':'刷新'}}</button></div></section><section class="remote-stats"><div class="panel"><small>服务器</small><strong>{{agents.length}}</strong></div><div class="panel"><small>在线</small><strong>{{onlineCount}}</strong></div><div class="panel"><small>离线</small><strong>{{agents.length-onlineCount}}</strong></div></section><section class="panel"><h2>服务器列表</h2><div class="agent-list"><article v-for="a in agents" :key="a.id" class="agent-card"><div><strong>{{a.name}}</strong><small>{{a.mine_name||''}} · {{a.hostname||'-'}} · Agent {{a.agent_version||'-'}} · {{Number(a.online)===1?'在线':'离线'}}</small></div><div class="row-actions"><button class="primary small-btn" :disabled="Number(a.online)!==1" @click="openFiles(a)">文件管理</button><a class="secondary small-btn" :href="'/admin/remote/terminal?agent='+a.id">诊断终端</a></div></article></div></section><section class="panel"><h2>远程运维审计</h2><div class="table-wrap"><table><thead><tr><th>时间</th><th>服务器</th><th>动作</th><th>详情</th></tr></thead><tbody><tr v-for="l in audit" :key="l.id"><td>{{time(l.create_time)}}</td><td>{{l.agent_name||'-'}}</td><td>{{l.action_type}}</td><td>{{l.detail||'-'}}</td></tr></tbody></table></div></section><div v-if="fileOpen" class="overlay" @click.self="fileOpen=false"><section class="files"><header><div><strong>{{fileAgent?.name}} · 文件管理</strong><code>{{filePath}}</code></div><div><button @click="up">上一级</button><button @click="mkdir">新建文件夹</button><button class="primary" @click="uploadInput.click()">上传文件</button><button @click="fileOpen=false">关闭</button><input ref="uploadInput" type="file" multiple hidden @change="uploadFiles"></div></header><div class="drop" @dragover.prevent @drop.prevent="uploadFiles({target:{files:$event.dataTransfer.files,value:''}})">拖拽文件到这里上传（当前单文件 ≤ 50MB）</div><table><thead><tr><th>名称</th><th>大小</th><th>权限</th><th>修改时间</th><th></th></tr></thead><tbody><tr v-if="fileLoading"><td colspan="5">读取中…</td></tr><tr v-for="x in fileItems" :key="x.name"><td><button class="link" @click="x.dir&&listFiles(join(x.name))">{{x.dir?'📁':'📄'}} {{x.name}}</button></td><td>{{x.dir?'-':size(x.size)}}</td><td><code>{{x.mode}}</code></td><td>{{time(x.modified)}}</td><td><button v-if="!x.dir" @click="downloadFile(x)">下载</button></td></tr></tbody></table></section></div></main></template>
<style scoped>.remote-page{display:grid;gap:20px}.remote-stats{display:grid;grid-template-columns:repeat(3,1fr);gap:14px}.remote-stats .panel{display:grid}.remote-stats strong{font-size:30px}.agent-list{display:grid;gap:10px}.agent-card{border:1px solid #e3e9f1;border-radius:12px;padding:14px;display:flex;justify-content:space-between;gap:15px}.agent-card>div:first-child{display:grid;gap:5px}.agent-card small{color:#77879c}.overlay{position:fixed;inset:0;background:#0008;z-index:1000;display:grid;place-items:center;padding:25px}.files{background:white;width:min(1200px,96vw);height:min(820px,92vh);border-radius:14px;padding:18px;overflow:auto}.files header{display:flex;justify-content:space-between;gap:15px;align-items:center}.files header>div{display:flex;gap:8px;align-items:center;flex-wrap:wrap}.drop{margin:15px 0;padding:24px;border:2px dashed #ccd5e0;border-radius:12px;text-align:center;color:#64748b}.files table{width:100%}.files th,.files td{text-align:left;padding:9px;border-bottom:1px solid #edf0f4}.link{border:0;background:none;cursor:pointer;text-align:left}@media(max-width:800px){.remote-stats{grid-template-columns:1fr}.agent-card,.files header{display:grid}}
</style>
